#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int* parseArray(const char* s, int* size) {
    int len = (int)strlen(s);
    if (len <= 2) { *size = 0; return NULL; }
    char* body = (char*)malloc((size_t)len - 1);
    memcpy(body, s + 1, (size_t)len - 2);
    body[len - 2] = '\0';

    int count = 1;
    for (int i = 0; body[i]; ++i) if (body[i] == ',') count++;

    int* arr = (int*)malloc((size_t)count * sizeof(int));
    int idx = 0;
    char* tok = strtok(body, ",");
    while (tok) {
        arr[idx++] = atoi(tok);
        tok = strtok(NULL, ",");
    }
    free(body);
    *size = idx;
    return arr;
}

int* findClosestElements(int* arr, int arrSize, int k, int x, int* returnSize) {
    int left = 0, right = arrSize - k;
    while (left < right) {
        int mid = left + (right - left) / 2;
        long long leftDist = (long long)x - arr[mid];
        long long rightDist = (long long)arr[mid + k] - x;
        if (leftDist > rightDist) left = mid + 1;
        else right = mid;
    }
    int* result = (int*)malloc((size_t)k * sizeof(int));
    for (int i = 0; i < k; ++i) result[i] = arr[left + i];
    *returnSize = k;
    return result;
}

