public class Main {
    static List<String> topLevel(String s) {
        List<String> parts = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') depth--;
            else if (c == ',' && depth == 0) {
                parts.add(s.substring(start, i).trim());
                start = i + 1;
            }
        }
        parts.add(s.substring(start).trim());
        return parts;
    }

    static int[] parseIntArray(String s) {
        s = s.trim();
        if (s.length() <= 2) return new int[0];
        String body = s.substring(1, s.length() - 1);
        List<String> parts = topLevel(body);
        int[] a = new int[parts.size()];
        for (int i = 0; i < parts.size(); i++) a[i] = Integer.parseInt(parts.get(i));
        return a;
    }

